def group_updates(updates):
    updates_dict = {}
    for key, value in updates:
        if key not in updates_dict:
            updates_dict[key] = []
        updates_dict[key].append(value)
    return list(updates_dict.items())

def merge_config(base, patch):
    if not isinstance(base, dict) or not isinstance(patch, dict):
        raise ValueError("Both base and patch must be dictionaries")

    merged = base.copy()
    for key, value in patch.items():
        if key in merged:
            if isinstance(merged[key], dict) and isinstance(value, dict):
                merged[key] = merge_config(merged[key], value)
            elif value is None:
                merged[key] = None
            else:
                merged[key] = value
        else:
            merged[key] = value

    return merged

import pathlib
from datetime import datetime

def report_paths(root):
    paths = []
    for path in pathlib.Path(root).iterdir():
        if path.is_file() and path.name.startswith("report-") and path.name.endswith(".csv"):
            date_str = path.name[7:-4]
            date_obj = datetime.strptime(date_str, "%Y-%m-%d")
            paths.append((date_obj, path))
    return sorted(paths, key=lambda x: x[0])

def page_bounds(page, size, total):
    if page <= 0 or size <= 0 or total < 0:
        raise ValueError("Invalid input values")
    start = max(0, min(page * size, total))
    return start, start + size

from typing import Dict, List, Tuple

def summarize_jobs(jobs: List[Job]) -> Dict[str, Tuple[int, int]]:
    summary = {}
    for job in jobs:
        status = job.status
        size = job.size
        if status not in summary:
            summary[status] = (0, 0)
        summary[status] = (summary[status][0] + 1, summary[status][1] + size)
    return {status: (count, total_size) for status, (count, total_size) in summary.items() if total_size != 0}

import time
from typing import Callable, Optional, Any

def retry_read(read: Callable[[], Any], attempts: int) -> Optional[Any]:
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    for attempt in range(attempts):
        try:
            return read()
        except TimeoutError:
            if attempt < attempts - 1:
                time.sleep(1)  # Wait for a second before retrying
            else:
                raise  # Propagate the final exception if all attempts fail

from collections import defaultdict

def iter_unique_events(events):
    seen_ids = defaultdict(list)
    for event in events:
        if event.get('id') is not None:
            seen_ids[event['id']].append(event)
    for id, events in seen_ids.items():
        yield events[0]

import csv

def render_row(fields, record, missing="-"):
    def escape(value):
        if value is None:
            return missing
        if isinstance(value, bool):
            return str(value).lower()
        if isinstance(value, str):
            value = value.replace("\\", "\\\\")
            value = value.replace("\t", "\\t")
            value = value.replace("\n", "\\n")
        return value

    return "\t".join(escape(field) for field in fields)
